functions.snippet:
function M.list()
  require("spotlight.ui.list").open("jump")
end

function M.list_remove()
  require("spotlight.ui.list").open("remove")
end

function M.persist_status()
  lib.notify(persist.status(0))
end

function M.spotlights()
  return registry.all()
end

function M.forget_window(win)
  ledger[win] = nil
end

function M.group(n)
  return ("Spotlight%d"):format(n)
end

function M.size()
  return #active_colors()
end

function M.reset()
  last = 0
end

function M.escape(text)
  return (text:gsub("\\", "\\\\"))
end

function M.on_change(fn)
  listeners[#listeners + 1] = fn
end

function M.all()
  return items
end

function M.count()
  return #items
end

function M.has_logger()
  return logger() ~= false
end

function M.root()
  local store = lib.try_require("lib.nvim.store.project")
  if store and type(store.root) == "function" then
    local ok, root = pcall(store.root)
    if ok and type(root) == "string" and root ~= "" then
      return slashes(root)
    end
  end
  return slashes(vim.fn.getcwd())
end

function M.next(count)
  return M.jump(1, count)
end

function M.prev(count)
  return M.jump(-1, count)
end

function M.has_override(key)
  return key ~= nil and exceptions[key] ~= nil
end

function M.exceptions()
  return exceptions
end

function M.setup()
  registry.on_change(function()
    M.save()
  end)
end
